package com.talkbot.plugin;
import com.talkbot.plugin.commands.TalkBotCommand;import com.talkbot.plugin.listener.ChatListener;import com.talkbot.plugin.manager.*;import org.bukkit.command.PluginCommand;import org.bukkit.plugin.java.JavaPlugin;
public final class TalkBotPlugin extends JavaPlugin {private DatabaseManager database;private BotRegistry registry;private ChatManager chat;
 public void onEnable(){saveDefaultConfig();database=new DatabaseManager(this);if(!database.open()){getServer().getPluginManager().disablePlugin(this);return;}registry=new BotRegistry(this,database);chat=new ChatManager(this,registry);PluginCommand cmd=getCommand("talkbot");if(cmd==null){getLogger().severe("Missing talkbot command in plugin.yml");getServer().getPluginManager().disablePlugin(this);return;}TalkBotCommand executor=new TalkBotCommand(this,registry,chat);cmd.setExecutor(executor);cmd.setTabCompleter(executor);getServer().getPluginManager().registerEvents(new ChatListener(this,chat),this);getLogger().info("TalkBot 3.0 enabled; registered bots: "+registry.getRegisteredBots().size());}
 public void reloadTalkBot(){reloadConfig();registry.reload();chat.reload();}public void onDisable(){if(chat!=null)chat.shutdown();if(database!=null)database.close();}public BotRegistry getBotRegistry(){return registry;}}
